record.field:
if record._name == 'stock.picking':
    pack = env['stock.picking'].search([
        ('origin', '=', record.name),
        ('state', 'not in', ['done', 'cancel']),
        ('picking_type_id.code', '=', 'outgoing')
    ], limit=1)

    if pack:
        action = {
            'type': 'ir.actions.client',
            'tag': 'barcode_picking_client_action',
            'params': {
                'barcode_picking_id': pack.id
            }
        }
    else:
        action = {'warning': 'Không tìm thấy phiếu pack liên quan chưa done.'}
